fn mask_eval(sh: &Shape, p: &Priv, data: &[Fp], point: &[Fp2]) -> Fp2 {
    let (log_n, n) = (row_log(sh, p.cm), 1usize << row_log(sh, p.cm));
    let logm = p.log.min(log_n);
    let c0 = if p.log < log_n { p.slices[0].0 % n } else { 0 };
    let eq = eq_table_msb(&point[p.log - logm..]);
    let re = &data[p.mask_row * n + c0..p.mask_row * n + c0 + eq.len()];
    let im = &data[(p.mask_row + 1) * n + c0..(p.mask_row + 1) * n + c0 + eq.len()];
    // Only the current site's fresh reserved pair is read. No cached private result.
    let (mut a, mut b, mut cross) = (Fp::ZERO, Fp::ZERO, Fp::ZERO);
    for ((e, x), y) in eq.iter().zip(re.iter()).zip(im.iter()) {
        a = a.add(e.c0.mul(*x));
        b = b.add(e.c1.mul(*y));
        cross = cross.add(e.c0.add(e.c1).mul(x.add(*y)));
    }
    Fp2::new(a.add(b.mul(Fp(7))), cross.sub(a).sub(b))
}
